import app from '../../forum/app';
import UserPage from './UserPage';
import ItemList from '../../common/utils/ItemList';
import Switch from '../../common/components/Switch';
import Button from '../../common/components/Button';
import FieldSet from '../../common/components/FieldSet';
import NotificationGrid from './NotificationGrid';
import ChangePasswordModal from './ChangePasswordModal';
import ChangeEmailModal from './ChangeEmailModal';
import listItems from '../../common/helpers/listItems';
import extractText from '../../common/utils/extractText';
import classList from '../../common/utils/classList';
import ThemeMode from '../../common/components/ThemeMode';
import { camelCaseToSnakeCase } from '../../common/utils/string';
import { isHapticSupported } from '../../common/utils/haptic';

/**
 * The `SettingsPage` component displays the user's settings control panel, in
 * the context of their user profile.
 */
export default class SettingsPage extends UserPage {
  oninit(vnode) {
    super.oninit(vnode);
    this.show(app.session.user);
    app.setTitle(extractText(app.translator.trans('core.forum.settings.title')));
  }
  content() {
    return m("div", {
      className: "SettingsPage"
    }, m("ul", null, listItems(this.settingsItems().toArray())));
  }
  sectionProps() {
    return {
      account: {
        className: 'FieldSet--col'
      },
      colorScheme: {
        className: 'FieldSet--col',
        visible: () => app.allowUserColorScheme
      }
    };
  }

  /**
   * Build an item list for the user's settings controls.
   */
  settingsItems() {
    const items = new ItemList();
    ['account', 'notifications', 'privacy', 'device', 'colorScheme'].forEach((section, index) => {
      const sectionItems = `${section}Items`;
      const {
        className,
        visible,
        ...props
      } = this.sectionProps()[section] || {};
      if (visible && visible() === false) return;
      const children = this[sectionItems]().toArray();
      if (!children.length) return;
      items.add(section, m(FieldSet, Object.assign({
        className: classList(`Settings-${section} FieldSet--min`, className || ''),
        label: app.translator.trans(`core.forum.settings.${camelCaseToSnakeCase(section)}_heading`)
      }, props), children), 100 - index * 10);
    });
    return items;
  }

  /**
   * Build an item list for the user's account settings.
   */
  accountItems() {
    const items = new ItemList();
    items.add('changePassword', m(Button, {
      className: "Button",
      onclick: () => app.modal.show(ChangePasswordModal)
    }, app.translator.trans('core.forum.settings.change_password_button')), 100);
    items.add('changeEmail', m(Button, {
      className: "Button",
      onclick: () => app.modal.show(ChangeEmailModal)
    }, app.translator.trans('core.forum.settings.change_email_button')), 90);
    return items;
  }

  /**
   * Build an item list for the user's notification settings.
   */
  notificationsItems() {
    const items = new ItemList();
    items.add('notificationGrid', m(NotificationGrid, {
      user: this.user
    }), 100);
    items.add('resetNotifications', m(Button, {
      className: "Button",
      onclick: this.resetNotificationPreferences.bind(this),
      loading: this.resettingNotifications
    }, app.translator.trans('core.forum.settings.reset_notifications_button')), 90);
    return items;
  }
  resettingNotifications = false;

  /**
   * Put every notification preference back to the forum's default. The server
   * forgets the user's choices in one save, so the registered defaults apply.
   */
  resetNotificationPreferences() {
    this.resettingNotifications = true;
    app.request({
      method: 'DELETE',
      url: `${app.forum.attribute('apiUrl')}/users/${this.user.id()}/notification-preferences`
    }).then(response => app.store.pushPayload(response)).finally(() => {
      this.resettingNotifications = false;
      m.redraw();
    });
  }

  /**
   * Build an item list for the user's privacy settings.
   */
  privacyItems() {
    const items = new ItemList();
    items.add('discloseOnline', m(Switch, {
      state: this.user.preferences()?.discloseOnline,
      onchange: value => {
        this.discloseOnlineLoading = true;
        this.user.savePreferences({
          discloseOnline: value
        }).then(() => {
          this.discloseOnlineLoading = false;
          m.redraw();
        });
      },
      loading: this.discloseOnlineLoading
    }, app.translator.trans('core.forum.settings.privacy_disclose_online_label')), 100);
    return items;
  }

  /**
   * Build an item list for the user's device settings.
   */
  deviceItems() {
    const items = new ItemList();
    if (!isHapticSupported) return items;
    items.add('hapticFeedback', m(Switch, {
      state: this.user.preferences()?.hapticFeedback,
      onchange: value => {
        this.hapticFeedbackLoading = true;
        this.user.savePreferences({
          hapticFeedback: value
        }).then(() => {
          this.hapticFeedbackLoading = false;
          m.redraw();
        });
      },
      loading: this.hapticFeedbackLoading
    }, app.translator.trans('core.forum.settings.haptic_feedback_label'), m("span", {
      className: "helpText"
    }, app.translator.trans('core.forum.settings.haptic_feedback_help'))), 100);
    return items;
  }

  /**
   * Color schemes.
   */
  colorSchemeItems() {
    const items = new ItemList();
    ThemeMode.colorSchemes.forEach(mode => {
      items.add(mode.id, m(ThemeMode, {
        mode: mode.id,
        label: mode.label || app.translator.trans('core.forum.settings.color_schemes.' + mode.id.replace('-', '_') + '_mode_label'),
        selected: this.user.preferences()?.colorScheme === mode.id,
        loading: this.colorSchemeLoading,
        onclick: () => {
          this.colorSchemeLoading = true;
          this.user.savePreferences({
            colorScheme: mode.id
          }).then(() => {
            this.colorSchemeLoading = false;
            app.setColorScheme(mode.id);
            m.redraw();
          });
        }
      }), 100);
    });
    return items;
  }
}
flarum.reg.add('core', 'forum/components/SettingsPage', SettingsPage);